modules.body:
;
    reg [7:0] a_memory [0:MAX_FRAME_BYTES-1];
    reg [7:0] b_memory [0:MAX_FRAME_BYTES-1];
    reg [POINTER_WIDTH-1:0] a_count, b_count, a_length, b_length, out_pointer;
    reg a_full, b_full, a_discard, b_discard;
    reg [15:0] a_vl, b_vl;
    reg [7:0] a_sn, b_sn;
    reg output_active, select_a;
    reg [31:0] cycle_count;
    reg [31:0] a_arrival, b_arrival;
    reg [HISTORY_DEPTH-1:0] history_valid;
    reg [15:0] history_vl [0:HISTORY_DEPTH-1];
    reg [7:0] history_sn [0:HISTORY_DEPTH-1];
    reg [31:0] history_time [0:HISTORY_DEPTH-1];
    localparam HISTORY_INDEX_WIDTH = HISTORY_DEPTH <= 1 ? 1 : $clog2(HISTORY_DEPTH);
    reg [HISTORY_INDEX_WIDTH-1:0] sweep_index, search_index, free_index, active_slot;
    reg search_active, search_a, search_duplicate, free_valid;
    reg [15:0] search_vl;
    reg [7:0] search_sn;
    reg candidate_a, candidate_valid;
    reg [15:0] candidate_vl;
    reg [7:0] candidate_sn;
    wire scan_live = history_valid[search_index] &&
        ((output_active && search_index == active_slot) ||
         (cycle_count-history_time[search_index]) < DEDUP_WINDOW_CYCLES);
    wire scan_match = scan_live && history_vl[search_index] == search_vl &&
                      history_sn[search_index] == search_sn;
    wire search_reject = search_duplicate || scan_match || search_sn == 0;
    assign duplicate_a_event = sys_rst_n && search_active && (search_duplicate || scan_match) && search_a;
    assign duplicate_b_event = sys_rst_n && search_active && (search_duplicate || scan_match) && !search_a;
    wire reserve_history = search_active && !search_reject &&
        search_index == HISTORY_DEPTH-1 && !output_active && (free_valid || !scan_live);
    wire [HISTORY_INDEX_WIDTH-1:0] reserve_index = free_valid ? free_index : search_index;
    wire a_candidate = a_full && !(output_active && select_a);
    wire b_candidate = b_full && !(output_active && !select_a);
    assign a_ready = sys_rst_n && !a_full;
    assign b_ready = sys_rst_n && !b_full;
    assign out_valid = sys_rst_n && output_active;
    assign out_data = select_a ? a_memory[out_pointer] : b_memory[out_pointer];

    assign out_vl_id = select_a ? a_vl : b_vl;
    assign out_sequence_number = select_a ? a_sn : b_sn;
    assign out_last = out_valid && (out_pointer ==
                     (select_a ? a_length : b_length)-1'b1);
    always @(posedge sys_clk) begin
        if (a_valid && a_ready && !a_discard && a_count < MAX_FRAME_BYTES)
            a_memory[a_count] <= a_data;
        if (b_valid && b_ready && !b_discard && b_count < MAX_FRAME_BYTES)
            b_memory[b_count] <= b_data;
    end
    always @* begin
        candidate_a = a_candidate && (!b_candidate ||
                      (cycle_count-a_arrival) >= (cycle_count-b_arrival));
        candidate_valid = a_candidate || b_candidate;
        candidate_vl = candidate_a ? a_vl : b_vl;
        candidate_sn = candidate_a ? a_sn : b_sn;
    end




    always @(posedge sys_clk) begin
        if (sys_rst_n && reserve_history) begin
            history_vl[reserve_index] <= search_vl;
            history_sn[reserve_index] <= search_sn;
            history_time[reserve_index] <= cycle_count;
        end else if (out_valid && out_ready && out_last)
            history_time[active_slot] <= cycle_count;
    end

    always @(posedge sys_clk or negedge sys_rst_n) begin
        if (!sys_rst_n) begin
            a_count <= 0; b_count <= 0; a_length <= 0; b_length <= 0;
            a_full <= 0; b_full <= 0; a_discard <= 0; b_discard <= 0;
            a_vl <= 0; b_vl <= 0; a_sn <= 0; b_sn <= 0;
            output_active <= 0; select_a <= 1; out_pointer <= 0;
            cycle_count <= 0; history_valid <= 0;
            a_arrival <= 0; b_arrival <= 0;
            active_slot <= 0; sweep_index <= 0; search_index <= 0; free_index <= 0;
            search_active <= 0; search_a <= 0; search_duplicate <= 0;
            free_valid <= 0; search_vl <= 0; search_sn <= 0;
        end else begin
            cycle_count <= cycle_count + 1'b1;


            if (history_valid[sweep_index] && !(output_active && sweep_index == active_slot) &&
                (cycle_count-history_time[sweep_index]) >= DEDUP_WINDOW_CYCLES)
                history_valid[sweep_index] <= 0;
            sweep_index <= sweep_index == HISTORY_DEPTH-1 ? 0 : sweep_index+1'b1;
            if (a_valid && a_ready) begin
                if (a_count == 0 && !a_discard) begin a_vl <= a_vl_id; a_sn <= a_sequence_number; end
                if (a_last) begin
                    a_count <= 0; a_discard <= 0;
                    if (!a_discard && a_count < MAX_FRAME_BYTES) begin
                        a_length <= a_count+1'b1; a_full <= 1; a_arrival <= cycle_count;
                    end
                end else if (!a_discard) begin
                    if (a_count == MAX_FRAME_BYTES-1) a_discard <= 1;
                    else a_count <= a_count+1'b1;
                end
            end
            if (b_valid && b_ready) begin
                if (b_count == 0 && !b_discard) begin b_vl <= b_vl_id; b_sn <= b_sequence_number; end
                if (b_last) begin
                    b_count <= 0; b_discard <= 0;
                    if (!b_discard && b_count < MAX_FRAME_BYTES) begin
                        b_length <= b_count+1'b1; b_full <= 1; b_arrival <= cycle_count;
                    end
                end else if (!b_discard) begin
                    if (b_count == MAX_FRAME_BYTES-1) b_discard <= 1;
                    else b_count <= b_count+1'b1;
                end
            end
            if (!search_active && candidate_valid) begin
                search_active <= 1;
                search_index <= 0;
                free_valid <= 0;
                search_a <= candidate_a;
                search_vl <= candidate_vl;
                search_sn <= candidate_sn;
                search_duplicate <= output_active &&
                    candidate_vl == (select_a ? a_vl : b_vl) &&
                    candidate_sn == (select_a ? a_sn : b_sn);
            end else if (search_active) begin
                if (search_reject) begin
                    search_active <= 0;
                    if (search_a) a_full <= 0;
                    else b_full <= 0;
                end else if (search_index == HISTORY_DEPTH-1) begin
                    search_active <= 0;
                    if (reserve_history) begin
                        history_valid[reserve_index] <= 1;
                        active_slot <= reserve_index;
                        output_active <= 1;
                        select_a <= search_a;
                        out_pointer <= 0;
                    end
                end else begin
                    if (!scan_live && !free_valid) begin free_index <= search_index; free_valid <= 1; end
                    search_index <= search_index+1'b1;
                end
            end
            if (out_valid && out_ready) begin
                if (out_last) begin


                    output_active <= 0;
                    if (select_a) a_full <= 0;
                    else b_full <= 0;
                end else out_pointer <= out_pointer+1'b1;
            end
        end
    end

;

    wire frame_capture_start;
    wire payload_write_valid;
    wire [7:0] payload_write_data;
    wire payload_write_ready;
    wire payload_write_overflow;
    wire frame_descriptor_ready;
    wire frame_commit;
    wire frame_abort;
    wire [10:0] frame_payload_length;
    wire [15:0] frame_vl_id;
    wire [7:0] frame_sequence_number;
    wire [7:0] guarded_data;
    wire guarded_valid, guarded_last, guarded_ready;
    wire ingress_complete, ingress_oversize, ingress_timeout, ingress_short;
    wire [4:0] decoder_errors;
    afdx_rx_ingress_guard #(.IDLE_TIMEOUT_CYCLES(RX_IDLE_TIMEOUT_CYCLES)) u_ingress_guard (
        .sys_clk(sys_clk),.sys_rst_n(sys_rst_n),
        .in_data(rx_data),.in_valid(rx_valid),.in_last(rx_last),.in_ready(rx_ready),
        .out_data(guarded_data),.out_valid(guarded_valid),.out_last(guarded_last),.out_ready(guarded_ready),
        .complete_event(ingress_complete),.oversize_event(ingress_oversize),
        .timeout_event(ingress_timeout),.short_event(ingress_short));
    assign rx_events = {rx_valid && !rx_ready && sys_rst_n, decoder_errors[4],
        decoder_errors[3],decoder_errors[2],decoder_errors[1],decoder_errors[0],
        ingress_short,ingress_timeout,ingress_oversize,
        frame_abort || ingress_short || ingress_timeout || ingress_oversize,
        frame_commit,ingress_complete};

    packet_decoder #(
        .LOCAL_DEST_IP(LOCAL_DEST_IP),
        .LOCAL_DEST_PORT(LOCAL_DEST_PORT),
        .ACCEPT_ANY_DEST(ACCEPT_ANY_DEST)
    ) u_packet_decoder (
        .sys_clk(sys_clk),
        .sys_rst_n(sys_rst_n),
        .rx_data(guarded_data),
        .rx_valid(guarded_valid),
        .rx_last(guarded_last),
        .rx_ready(guarded_ready),
        .frame_capture_start(frame_capture_start),
        .payload_write_valid(payload_write_valid),
        .payload_write_data(payload_write_data),
        .payload_write_ready(payload_write_ready),
        .payload_write_overflow(payload_write_overflow),
        .frame_descriptor_ready(frame_descriptor_ready),
        .frame_commit(frame_commit),
        .frame_abort(frame_abort),
        .frame_vl_id(frame_vl_id),
        .frame_sequence_number(frame_sequence_number),
        .frame_payload_length(frame_payload_length),
        .error_events(decoder_errors)
    );

    afdx_rx_frame_manager u_frame_manager (
        .sys_clk(sys_clk),
        .sys_rst_n(sys_rst_n),
        .frame_capture_start(frame_capture_start),
        .payload_write_valid(payload_write_valid),
        .payload_write_data(payload_write_data),
        .payload_write_ready(payload_write_ready),
        .payload_write_overflow(payload_write_overflow),
        .frame_descriptor_ready(frame_descriptor_ready),
        .frame_commit(frame_commit),
        .frame_abort(frame_abort),
        .frame_vl_id(frame_vl_id),
        .frame_sequence_number(frame_sequence_number),
        .frame_payload_length(frame_payload_length),
        .app_rx_data(app_rx_data),
        .app_rx_valid(app_rx_valid),
        .app_rx_last(app_rx_last),
        .app_rx_vl_id(app_rx_vl_id),
        .app_rx_sequence_number(app_rx_sequence_number),
        .app_rx_ready(app_rx_ready)
    );

;
    localparam integer COUNTER_COUNT = 36;
    localparam integer TIMEOUT_WIDTH = APP_IDLE_TIMEOUT_CYCLES <= 1 ? 1 : $clog2(APP_IDLE_TIMEOUT_CYCLES);
    reg [31:0] counters [0:COUNTER_COUNT-1];
    reg [10:0] tx_app_bytes;
    reg tx_partial, tx_oversize_seen, tx_timeout_seen;
    reg [TIMEOUT_WIDTH-1:0] tx_idle_count;
    wire tx_transfer = app_tx_valid && app_tx_ready;
    wire tx_oversize_event = tx_transfer && !tx_oversize_seen && tx_app_bytes == 1471;
    wire tx_timeout_event = tx_partial && !tx_timeout_seen && app_tx_ready &&
                            !app_tx_valid && tx_idle_count == APP_IDLE_TIMEOUT_CYCLES-1;
    wire [35:0] all_events = events | {28'd0,tx_timeout_event,tx_oversize_event,6'd0};
    integer i;
    assign read_error = (read_addr[1:0] != 0) || (read_addr[7:2] >= COUNTER_COUNT);
    always @* begin
        read_data = 0;
        if (!read_error) read_data = counters[read_addr[7:2]];
    end
    always @(posedge sys_clk or negedge sys_rst_n) begin
        if (!sys_rst_n) begin
            for (i=0;i<COUNTER_COUNT;i=i+1) counters[i] <= 0;
        end else if (clear) begin
            for (i=0;i<COUNTER_COUNT;i=i+1) counters[i] <= 0;
        end else begin
            for (i=0;i<COUNTER_COUNT;i=i+1)
                if (all_events[i] && counters[i] != 32'hffffffff)
                    counters[i] <= counters[i]+1'b1;
        end
    end
    always @(posedge sys_clk or negedge sys_rst_n) begin
        if (!sys_rst_n) begin
            tx_app_bytes <= 0; tx_partial <= 0;
            tx_oversize_seen <= 0; tx_timeout_seen <= 0; tx_idle_count <= 0;
        end else if (tx_transfer) begin
            tx_idle_count <= 0;
            if (app_tx_last) begin
                tx_app_bytes <= 0; tx_partial <= 0;
                tx_oversize_seen <= 0; tx_timeout_seen <= 0;
            end else begin
                tx_partial <= 1;
                if (tx_app_bytes < 1472) tx_app_bytes <= tx_app_bytes+1'b1;
                if (tx_oversize_event) tx_oversize_seen <= 1;
            end
        end else if (tx_timeout_event) tx_timeout_seen <= 1;
        else if (tx_partial && !tx_timeout_seen && app_tx_ready && !app_tx_valid)
            tx_idle_count <= tx_idle_count+1'b1;
    end

;


    wire [15:0] padded_payload_length;
    wire [15:0] udp_length;
    wire [15:0] ip_total_length;


    wire [31:0] ip_checksum_sum;
    wire [16:0] ip_checksum_fold_1;
    wire [16:0] ip_checksum_fold_2;
    wire [15:0] ip_header_checksum;


    assign padded_payload_length = (payload_frame_length < 17) ?
                                   16'd17 : payload_frame_length;
    assign udp_length      = 16'd8 + padded_payload_length + 16'd1;
    assign ip_total_length = 16'd20 + udp_length;



    assign ip_checksum_sum = 32'h0000_4500 +
                             {16'd0, ip_total_length} +
                             32'h0000_0000 +
                             32'h0000_4000 +
                             32'h0000_4011 +
                             {16'd0, SRC_IP[31:16]} +
                             {16'd0, SRC_IP[15:0]} +
                             {16'd0, DEST_IP[31:16]} +
                             {16'd0, DEST_IP[15:0]};

    assign ip_checksum_fold_1 = ip_checksum_sum[15:0] +
                                ip_checksum_sum[31:16];
    assign ip_checksum_fold_2 = ip_checksum_fold_1[15:0] +
                                ip_checksum_fold_1[16];
    assign ip_header_checksum = ~ip_checksum_fold_2[15:0];



    always @(*) begin
        case (header_byte_index)

            6'd0:  header_byte_data = DEST_MAC[47:40];
            6'd1:  header_byte_data = DEST_MAC[39:32];
            6'd2:  header_byte_data = DEST_MAC[31:24];
            6'd3:  header_byte_data = DEST_MAC[23:16];
            6'd4:  header_byte_data = DEST_MAC[15:8];
            6'd5:  header_byte_data = DEST_MAC[7:0];
            6'd6:  header_byte_data = SRC_MAC[47:40];
            6'd7:  header_byte_data = SRC_MAC[39:32];
            6'd8:  header_byte_data = SRC_MAC[31:24];
            6'd9:  header_byte_data = SRC_MAC[23:16];
            6'd10: header_byte_data = SRC_MAC[15:8];
            6'd11: header_byte_data = SRC_MAC[7:0];
            6'd12: header_byte_data = 8'h08;
            6'd13: header_byte_data = 8'h00;


            6'd14: header_byte_data = 8'h45;
            6'd15: header_byte_data = 8'h00;
            6'd16: header_byte_data = ip_total_length[15:8];
            6'd17: header_byte_data = ip_total_length[7:0];
            6'd18: header_byte_data = 8'h00;
            6'd19: header_byte_data = 8'h00;
            6'd20: header_byte_data = 8'h40;
            6'd21: header_byte_data = 8'h00;
            6'd22: header_byte_data = 8'h40;
            6'd23: header_byte_data = 8'h11;
            6'd24: header_byte_data = ip_header_checksum[15:8];
            6'd25: header_byte_data = ip_header_checksum[7:0];
            6'd26: header_byte_data = SRC_IP[31:24];
            6'd27: header_byte_data = SRC_IP[23:16];
            6'd28: header_byte_data = SRC_IP[15:8];
            6'd29: header_byte_data = SRC_IP[7:0];
            6'd30: header_byte_data = DEST_IP[31:24];
            6'd31: header_byte_data = DEST_IP[23:16];
            6'd32: header_byte_data = DEST_IP[15:8];
            6'd33: header_byte_data = DEST_IP[7:0];


            6'd34: header_byte_data = SRC_PORT[15:8];
            6'd35: header_byte_data = SRC_PORT[7:0];
            6'd36: header_byte_data = DEST_PORT[15:8];
            6'd37: header_byte_data = DEST_PORT[7:0];
            6'd38: header_byte_data = udp_length[15:8];
            6'd39: header_byte_data = udp_length[7:0];
            6'd40: header_byte_data = 8'h00;
            6'd41: header_byte_data = 8'h00;

            default: header_byte_data = 8'h00;
        endcase
    end

;
    reg [7:0] memory [0:MAX_FRAME_BYTES-1];
    reg [POINTER_WIDTH-1:0] capture_count, frame_length;
    reg [POINTER_WIDTH-1:0] a_pointer, b_pointer;
    reg a_pending, b_pending, complete, discard;
    localparam BAG_WIDTH = BAG_CYCLES <= 1 ? 1 : $clog2(BAG_CYCLES);
    reg [BAG_WIDTH-1:0] a_cooldown, b_cooldown;
    assign oversize_event = sys_rst_n && in_valid && in_ready && !discard &&
        capture_count == MAX_FRAME_BYTES-1 && !in_last;
    assign in_ready = sys_rst_n && !complete;


    assign a_valid = sys_rst_n && complete && a_pending &&
                     (a_pointer != 0 || a_cooldown == 0);
    assign b_valid = sys_rst_n && complete && b_pending &&
                     (b_pointer != 0 || b_cooldown == 0);
    assign a_data = memory[a_pointer];
    assign b_data = memory[b_pointer];
    assign a_last = a_valid && (a_pointer == frame_length-1'b1);
    assign b_last = b_valid && (b_pointer == frame_length-1'b1);


    always @(posedge sys_clk)
        if (in_valid && in_ready && !discard && capture_count < MAX_FRAME_BYTES)
            memory[capture_count] <= in_data;
    always @(posedge sys_clk or negedge sys_rst_n) begin
        if (!sys_rst_n) begin
            capture_count <= 0; frame_length <= 0;
            a_pointer <= 0; b_pointer <= 0;
            a_pending <= 0; b_pending <= 0; complete <= 0; discard <= 0;
            a_cooldown <= 0; b_cooldown <= 0;
        end else begin
            if (a_cooldown != 0) a_cooldown <= a_cooldown-1'b1;
            if (b_cooldown != 0) b_cooldown <= b_cooldown-1'b1;
            if (in_valid && in_ready) begin
                if (in_last) begin
                    capture_count <= 0;
                    discard <= 0;
                    if (!discard && capture_count < MAX_FRAME_BYTES) begin
                        frame_length <= capture_count + 1'b1;
                        a_pointer <= 0; b_pointer <= 0;
                        a_pending <= 1;
                        b_pending <= 1;
                        complete <= 1;
                    end
                end else if (!discard) begin
                    if (capture_count == MAX_FRAME_BYTES-1) discard <= 1;
                    else capture_count <= capture_count + 1'b1;
                end
            end
            if (a_valid && a_ready) begin
                if (a_pointer == 0) a_cooldown <= BAG_CYCLES-1;
                if (a_last) a_pending <= 0;
                else a_pointer <= a_pointer + 1'b1;
            end
            if (b_valid && b_ready) begin
                if (b_pointer == 0) b_cooldown <= BAG_CYCLES-1;
                if (b_last) b_pending <= 0;
                else b_pointer <= b_pointer + 1'b1;
            end
            if (complete && !a_pending && !b_pending) complete <= 0;
        end
    end

;

    reg [7:0] payload_memory [0:PAYLOAD_FIFO_DEPTH-1];
    reg [PAYLOAD_POINTER_WIDTH-1:0] payload_write_pointer;
    reg [PAYLOAD_POINTER_WIDTH-1:0] payload_read_pointer;
    reg [PAYLOAD_POINTER_WIDTH:0] stored_payload_byte_count;

    reg [PAYLOAD_POINTER_WIDTH-1:0] frame_capture_start_pointer;

    reg [PAYLOAD_POINTER_WIDTH:0] candidate_payload_length;
    reg frame_capture_active;
    reg frame_discard_active;

    reg [FRAME_LENGTH_WIDTH-1:0] descriptor_length_memory
        [0:DESCRIPTOR_FIFO_DEPTH-1];
    reg [15:0] descriptor_vl_memory [0:DESCRIPTOR_FIFO_DEPTH-1];
    reg [7:0] descriptor_sn_memory [0:DESCRIPTOR_FIFO_DEPTH-1];
    reg [DESCRIPTOR_POINTER_WIDTH-1:0] descriptor_write_pointer;
    reg [DESCRIPTOR_POINTER_WIDTH-1:0] descriptor_read_pointer;
    reg [DESCRIPTOR_POINTER_WIDTH:0] descriptor_count;

    reg app_rx_frame_active;
    reg [FRAME_LENGTH_WIDTH-1:0] app_rx_bytes_remaining;
    reg [7:0] app_rx_data_register;
    reg app_rx_valid_register;
    reg app_rx_last_register;

    wire descriptor_full;
    wire descriptor_empty;
    wire descriptor_write_enable;
    wire descriptor_read_enable;
    wire app_rx_transfer;
    wire payload_read_enable;
    wire payload_space_available;
    wire candidate_payload_write;
    wire frame_rollback;
    wire candidate_buffer_exhausted;
    wire [PAYLOAD_POINTER_WIDTH:0] rollback_byte_count;

    assign descriptor_full =
        (descriptor_count == DESCRIPTOR_FIFO_DEPTH);
    assign descriptor_empty = (descriptor_count == 0);
    assign descriptor_read_enable = !app_rx_frame_active &&
                                    !app_rx_valid_register &&
                                    !descriptor_empty;
    assign frame_descriptor_ready = !descriptor_full ||
                                    descriptor_read_enable;


    assign payload_write_ready = frame_discard_active ||
                                 (payload_space_available &&
                                  frame_descriptor_ready);
    assign descriptor_write_enable = frame_commit &&
                                     frame_capture_active &&
                                     !frame_discard_active &&
                                     !payload_write_overflow &&
                                     frame_descriptor_ready;

    assign app_rx_data = app_rx_data_register;
    assign app_rx_valid = app_rx_valid_register;
    assign app_rx_last = app_rx_last_register;
    assign app_rx_transfer = app_rx_valid && app_rx_ready;


    assign payload_read_enable = sys_rst_n && app_rx_frame_active &&
                                 (app_rx_bytes_remaining != 0) &&
                                 (!app_rx_valid_register || app_rx_ready);

    assign payload_space_available =
        (stored_payload_byte_count < PAYLOAD_FIFO_DEPTH) ||
        payload_read_enable;
    assign candidate_payload_write = payload_write_valid &&
                                     frame_capture_active &&
                                     !frame_discard_active &&
                                     !payload_write_overflow &&
                                     payload_space_available;


    assign candidate_buffer_exhausted = frame_capture_active &&
                                       !frame_discard_active &&
                                       (candidate_payload_length ==
                                        PAYLOAD_FIFO_DEPTH);
    assign frame_rollback = frame_capture_active && !frame_discard_active &&
                            (frame_abort || candidate_buffer_exhausted);
    assign rollback_byte_count = candidate_payload_length;

    always @(posedge sys_clk) begin
        if (candidate_payload_write)
            payload_memory[payload_write_pointer] <= payload_write_data;
    end


    always @(posedge sys_clk or negedge sys_rst_n) begin
        if (sys_rst_n == 1'b0) begin
            frame_capture_start_pointer <= {PAYLOAD_POINTER_WIDTH{1'b0}};
            candidate_payload_length <= {(PAYLOAD_POINTER_WIDTH + 1){1'b0}};
            frame_capture_active <= 1'b0;
            frame_discard_active <= 1'b0;
            payload_write_overflow <= 1'b0;
        end else begin
            if (frame_capture_start) begin
                frame_capture_start_pointer <= payload_write_pointer;
                candidate_payload_length <= {(PAYLOAD_POINTER_WIDTH + 1){1'b0}};
                frame_capture_active <= 1'b1;
                frame_discard_active <= 1'b0;
                payload_write_overflow <= 1'b0;
            end

            if (candidate_payload_write)
                candidate_payload_length <= candidate_payload_length + 1'b1;
            else if (payload_write_valid && frame_capture_active &&
                     !payload_space_available)
                payload_write_overflow <= 1'b1;

            if (candidate_buffer_exhausted) begin
                candidate_payload_length <= {(PAYLOAD_POINTER_WIDTH + 1){1'b0}};
                frame_discard_active <= 1'b1;
                payload_write_overflow <= 1'b1;
            end

            if (frame_abort || descriptor_write_enable) begin
                candidate_payload_length <= {(PAYLOAD_POINTER_WIDTH + 1){1'b0}};
                frame_capture_active <= 1'b0;
                frame_discard_active <= 1'b0;
                payload_write_overflow <= 1'b0;
            end
        end
    end


    always @(posedge sys_clk or negedge sys_rst_n) begin
        if (sys_rst_n == 1'b0) begin
            payload_write_pointer <= {PAYLOAD_POINTER_WIDTH{1'b0}};
            payload_read_pointer <= {PAYLOAD_POINTER_WIDTH{1'b0}};
            stored_payload_byte_count <=
                {(PAYLOAD_POINTER_WIDTH + 1){1'b0}};
        end else begin
            if (frame_rollback)
                payload_write_pointer <= frame_capture_start_pointer;
            else if (candidate_payload_write)
                payload_write_pointer <= payload_write_pointer + 1'b1;

            if (payload_read_enable)
                payload_read_pointer <= payload_read_pointer + 1'b1;

            if (frame_rollback)
                stored_payload_byte_count <= stored_payload_byte_count -
                    rollback_byte_count - payload_read_enable;
            else begin
                case ({candidate_payload_write, payload_read_enable})
                    2'b10: stored_payload_byte_count <=
                        stored_payload_byte_count + 1'b1;
                    2'b01: stored_payload_byte_count <=
                        stored_payload_byte_count - 1'b1;
                    default: stored_payload_byte_count <=
                        stored_payload_byte_count;
                endcase
            end
        end
    end


    always @(posedge sys_clk) begin
        if (descriptor_write_enable) begin
            descriptor_length_memory[descriptor_write_pointer] <= frame_payload_length;
            descriptor_vl_memory[descriptor_write_pointer] <= frame_vl_id;
            descriptor_sn_memory[descriptor_write_pointer] <= frame_sequence_number;
        end
    end

    always @(posedge sys_clk or negedge sys_rst_n) begin
        if (sys_rst_n == 1'b0) begin
            descriptor_write_pointer <=
                {DESCRIPTOR_POINTER_WIDTH{1'b0}};
            descriptor_read_pointer <=
                {DESCRIPTOR_POINTER_WIDTH{1'b0}};
            descriptor_count <=
                {(DESCRIPTOR_POINTER_WIDTH + 1){1'b0}};
        end else begin
            if (descriptor_write_enable)
                descriptor_write_pointer <= descriptor_write_pointer + 1'b1;
            if (descriptor_read_enable)
                descriptor_read_pointer <= descriptor_read_pointer + 1'b1;

            case ({descriptor_write_enable, descriptor_read_enable})
                2'b10: descriptor_count <= descriptor_count + 1'b1;
                2'b01: descriptor_count <= descriptor_count - 1'b1;
                default: descriptor_count <= descriptor_count;
            endcase
        end
    end


    always @(posedge sys_clk or negedge sys_rst_n) begin
        if (sys_rst_n == 1'b0) begin
            app_rx_frame_active <= 1'b0;
            app_rx_vl_id <= 0;
            app_rx_sequence_number <= 0;
            app_rx_bytes_remaining <= {FRAME_LENGTH_WIDTH{1'b0}};
        end else begin
            if (descriptor_read_enable) begin
                app_rx_vl_id <= descriptor_vl_memory[descriptor_read_pointer];
                app_rx_sequence_number <= descriptor_sn_memory[descriptor_read_pointer];
                app_rx_frame_active <= 1'b1;
                app_rx_bytes_remaining <=
                    descriptor_length_memory[descriptor_read_pointer];
            end else if (payload_read_enable) begin
                if (app_rx_bytes_remaining == 1) begin
                    app_rx_bytes_remaining <=
                        {FRAME_LENGTH_WIDTH{1'b0}};
                    app_rx_frame_active <= 1'b0;
                end else
                    app_rx_bytes_remaining <= app_rx_bytes_remaining - 1'b1;
            end
        end
    end

    always @(posedge sys_clk or negedge sys_rst_n) begin
        if (sys_rst_n == 1'b0) begin
            app_rx_data_register <= 8'd0;
            app_rx_valid_register <= 1'b0;
            app_rx_last_register <= 1'b0;
        end else begin
            if (payload_read_enable) begin
                app_rx_data_register <= payload_memory[payload_read_pointer];
                app_rx_valid_register <= 1'b1;
                app_rx_last_register <= (app_rx_bytes_remaining == 1);
            end else if (app_rx_transfer) begin
                app_rx_valid_register <= 1'b0;
                app_rx_last_register <= 1'b0;
            end
        end
    end

;
    reg [7:0] memory [0:MAX_FRAME_BYTES-1];
    reg [POINTER_WIDTH-1:0] capture_count, frame_length, read_pointer;
    reg capturing, dropping, complete;
    localparam integer TIMEOUT_WIDTH = IDLE_TIMEOUT_CYCLES <= 1 ? 1 : $clog2(IDLE_TIMEOUT_CYCLES);
    reg [TIMEOUT_WIDTH-1:0] idle_count;
    wire transfer = in_valid && in_ready;
    wire idle_expired = sys_rst_n && capturing && !complete && !in_valid &&
                        (idle_count == IDLE_TIMEOUT_CYCLES-1);
    assign in_ready = sys_rst_n && !complete;
    assign out_valid = sys_rst_n && complete;
    assign out_data = memory[read_pointer];
    assign out_last = out_valid && (read_pointer == frame_length-1'b1);

    assign oversize_event = transfer && !dropping && !in_last &&
                            (capture_count == MAX_FRAME_BYTES-1);
    assign short_event = transfer && !dropping && in_last &&
                         (capture_count < MIN_FRAME_BYTES-1);
    assign timeout_event = idle_expired && !dropping;
    assign complete_event = transfer && !dropping && in_last &&
                            (capture_count >= MIN_FRAME_BYTES-1);
    always @(posedge sys_clk) begin
        if (transfer && !dropping) memory[capture_count] <= in_data;
    end
    always @(posedge sys_clk or negedge sys_rst_n) begin
        if (!sys_rst_n) begin
            capture_count <= 0; frame_length <= 0; read_pointer <= 0;
            capturing <= 0; dropping <= 0; complete <= 0; idle_count <= 0;
        end else begin
            if (out_valid && out_ready) begin
                if (out_last) begin complete <= 0; read_pointer <= 0; end
                else read_pointer <= read_pointer+1'b1;
            end
            if (transfer) begin
                idle_count <= 0;
                if (in_last) begin
                    capturing <= 0; dropping <= 0; capture_count <= 0;
                    if (complete_event) begin
                        complete <= 1; frame_length <= capture_count+1'b1;
                        read_pointer <= 0;
                    end
                end else begin
                    capturing <= 1;
                    if (oversize_event) begin dropping <= 1; capture_count <= 0; end
                    else if (!dropping) capture_count <= capture_count+1'b1;
                end
            end else if (idle_expired) begin

                capturing <= 0; dropping <= 0; capture_count <= 0; idle_count <= 0;
            end else if (capturing && !complete && !in_valid)
                idle_count <= idle_count+1'b1;
        end
    end

;

    localparam [15:0] MIN_UDP_LENGTH  = 16'd26;
    localparam [15:0] MAX_UDP_LENGTH  = 16'd1480;
    localparam [15:0] MAX_CORE_LENGTH = 16'd1514;























    reg        frame_active;
    reg [11:0] rx_byte_index;
    reg        frame_length_exceeded;
    reg [FRAME_LENGTH_WIDTH-1:0] payload_byte_count;

    reg [47:0] destination_mac;
    reg [15:0] ether_type;
    reg [7:0]  ip_version_ihl;
    reg [15:0] ip_total_length;
    reg [7:0]  ip_protocol;
    reg [31:0] source_ip;
    reg [31:0] destination_ip;
    reg [15:0] udp_destination_port;
    reg [15:0] udp_length;
    reg [15:0] udp_checksum_field;

    reg [7:0]  ip_word_high;
    reg [16:0] ip_checksum_sum;
    reg [7:0]  udp_word_high;
    reg [16:0] udp_checksum_sum;

    wire active_frame_end;
    wire [15:0] received_frame_length;
    wire [15:0] expected_ip_frame_length;
    wire [15:0] expected_udp_frame_length;
    wire [15:0] decoded_payload_length;
    wire protocol_valid;
    wire length_valid;
    wire checksum_valid;
    wire ip_checksum_valid;
    wire udp_checksum_valid;
    wire [15:0] udp_last_word;
    wire [16:0] udp_sum_with_last;
    wire [16:0] udp_sum_pseudo_1;
    wire [16:0] udp_sum_pseudo_2;
    wire [16:0] udp_sum_pseudo_3;
    wire [16:0] udp_sum_pseudo_4;
    wire [16:0] udp_sum_pseudo_5;
    wire [16:0] udp_sum_pseudo_6;

    assign frame_capture_start = rx_transfer && !frame_active;
    assign payload_write_valid = rx_transfer && frame_active &&
                                 (rx_byte_index >= 12'd42) && !rx_last;
    assign payload_write_data = rx_data;
    assign frame_parse_done = rx_transfer && rx_last;
    assign active_frame_end = frame_parse_done && frame_active;

    assign parsed_payload_length = payload_byte_count;
    assign parsed_vl_id = destination_mac[15:0];
    assign parsed_sequence_number = rx_data;

    assign received_frame_length = {4'd0, rx_byte_index} + 16'd1;
    assign expected_ip_frame_length = 16'd14 + ip_total_length;
    assign expected_udp_frame_length = 16'd34 + udp_length;
    assign decoded_payload_length = udp_length - 16'd9;

    assign protocol_valid =
        (destination_mac[47:16] == 32'h03_00_00_00) &&
        (ether_type == 16'h0800) &&
        (ip_version_ihl == 8'h45) &&
        (ip_protocol == 8'd17) &&
        (ACCEPT_ANY_DEST || ((destination_ip == LOCAL_DEST_IP) &&
                             (udp_destination_port == LOCAL_DEST_PORT)));

    assign length_valid = active_frame_end &&
        (received_frame_length >= 16'd60) &&
        (received_frame_length <= MAX_CORE_LENGTH) &&
        (received_frame_length == expected_ip_frame_length) &&
        (received_frame_length == expected_udp_frame_length) &&
        (ip_total_length == (16'd20 + udp_length)) &&
        (udp_length >= MIN_UDP_LENGTH) &&
        (udp_length <= MAX_UDP_LENGTH) &&
        (decoded_payload_length == payload_byte_count) &&
        !frame_length_exceeded;

    assign ip_checksum_valid =
        (checksum_fold(ip_checksum_sum) == 16'hffff);

    assign udp_last_word = rx_byte_index[0] ?
                           {udp_word_high, rx_data} : {rx_data, 8'h00};
    assign udp_sum_with_last = checksum_add(udp_checksum_sum,
                                            udp_last_word);
    assign udp_sum_pseudo_1 = checksum_add(udp_sum_with_last,
                                           source_ip[31:16]);
    assign udp_sum_pseudo_2 = checksum_add(udp_sum_pseudo_1,
                                           source_ip[15:0]);
    assign udp_sum_pseudo_3 = checksum_add(udp_sum_pseudo_2,
                                           destination_ip[31:16]);
    assign udp_sum_pseudo_4 = checksum_add(udp_sum_pseudo_3,
                                           destination_ip[15:0]);
    assign udp_sum_pseudo_5 = checksum_add(udp_sum_pseudo_4,
                                           16'h0011);
    assign udp_sum_pseudo_6 = checksum_add(udp_sum_pseudo_5,
                                           udp_length);
    assign udp_checksum_valid = (udp_checksum_field == 16'h0000) ||
                                (checksum_fold(udp_sum_pseudo_6) ==
                                 16'hffff);
    assign checksum_valid = active_frame_end &&
                            ip_checksum_valid && udp_checksum_valid;

    assign frame_parse_valid = active_frame_end && protocol_valid &&
                               length_valid && checksum_valid;

    always @(posedge sys_clk or negedge sys_rst_n) begin
        if (sys_rst_n == 1'b0) begin
            frame_active         <= 1'b0;
            rx_byte_index        <= 12'd0;
            frame_length_exceeded <= 1'b0;
            payload_byte_count   <= {FRAME_LENGTH_WIDTH{1'b0}};
            destination_mac      <= 48'd0;
            ether_type           <= 16'd0;
            ip_version_ihl       <= 8'd0;
            ip_total_length      <= 16'd0;
            ip_protocol          <= 8'd0;
            source_ip            <= 32'd0;
            destination_ip       <= 32'd0;
            udp_destination_port <= 16'd0;
            udp_length           <= 16'd0;
            udp_checksum_field   <= 16'd0;
            ip_word_high         <= 8'd0;
            ip_checksum_sum      <= 17'd0;
            udp_word_high        <= 8'd0;
            udp_checksum_sum     <= 17'd0;
        end
        else if (rx_transfer == 1'b1) begin
            if (frame_active == 1'b0) begin
                frame_active         <= !rx_last;
                rx_byte_index        <= rx_last ? 12'd0 : 12'd1;
                frame_length_exceeded <= 1'b0;
                payload_byte_count   <= {FRAME_LENGTH_WIDTH{1'b0}};
                destination_mac      <= {40'd0, rx_data};
                ether_type           <= 16'd0;
                ip_version_ihl       <= 8'd0;
                ip_total_length      <= 16'd0;
                ip_protocol          <= 8'd0;
                source_ip            <= 32'd0;
                destination_ip       <= 32'd0;
                udp_destination_port <= 16'd0;
                udp_length           <= 16'd0;
                udp_checksum_field   <= 16'd0;
                ip_word_high         <= 8'd0;
                ip_checksum_sum      <= 17'd0;
                udp_word_high        <= 8'd0;
                udp_checksum_sum     <= 17'd0;
            end
            else begin
                if (rx_last == 1'b1) begin
                    frame_active       <= 1'b0;
                    rx_byte_index      <= 12'd0;
                    payload_byte_count <= {FRAME_LENGTH_WIDTH{1'b0}};
                end
                else begin
                    rx_byte_index <= rx_byte_index + 1'b1;
                    if (rx_byte_index >= (MAX_CORE_LENGTH - 1'b1))
                        frame_length_exceeded <= 1'b1;
                    if (rx_byte_index >= 12'd42)
                        payload_byte_count <= payload_byte_count + 1'b1;
                end

                if (rx_byte_index <= 12'd5)
                    destination_mac <= {destination_mac[39:0], rx_data};

                case (rx_byte_index)
                    12'd12: ether_type[15:8] <= rx_data;
                    12'd13: ether_type[7:0]  <= rx_data;
                    12'd14: ip_version_ihl   <= rx_data;
                    12'd16: ip_total_length[15:8] <= rx_data;
                    12'd17: ip_total_length[7:0]  <= rx_data;
                    12'd23: ip_protocol <= rx_data;
                    12'd26: source_ip[31:24] <= rx_data;
                    12'd27: source_ip[23:16] <= rx_data;
                    12'd28: source_ip[15:8]  <= rx_data;
                    12'd29: source_ip[7:0]   <= rx_data;
                    12'd30: destination_ip[31:24] <= rx_data;
                    12'd31: destination_ip[23:16] <= rx_data;
                    12'd32: destination_ip[15:8]  <= rx_data;
                    12'd33: destination_ip[7:0]   <= rx_data;
                    12'd36: udp_destination_port[15:8] <= rx_data;
                    12'd37: udp_destination_port[7:0]  <= rx_data;
                    12'd38: udp_length[15:8] <= rx_data;
                    12'd39: udp_length[7:0]  <= rx_data;
                    12'd40: udp_checksum_field[15:8] <= rx_data;
                    12'd41: udp_checksum_field[7:0]  <= rx_data;
                    default: begin
                    end
                endcase

                if ((rx_byte_index >= 12'd14) &&
                    (rx_byte_index <= 12'd33)) begin
                    if (rx_byte_index[0] == 1'b0)
                        ip_word_high <= rx_data;
                    else
                        ip_checksum_sum <= checksum_add(
                            ip_checksum_sum, {ip_word_high, rx_data});
                end

                if (rx_byte_index >= 12'd34) begin
                    if (rx_byte_index[0] == 1'b0)
                        udp_word_high <= rx_data;
                    else
                        udp_checksum_sum <= checksum_add(
                            udp_checksum_sum, {udp_word_high, rx_data});
                end
            end
        end
    end

;

    localparam integer VL_TABLE_DEPTH = (1 << VL_INDEX_WIDTH);
    localparam [1:0] CHECK_IDLE = 2'd0;
    localparam [1:0] CHECK_READ = 2'd1;
    localparam [1:0] CHECK_COMPARE = 2'd2;

    reg [15:0] vl_tag_memory [0:VL_TABLE_DEPTH-1];
    reg [7:0]  sequence_number_memory [0:VL_TABLE_DEPTH-1];
    reg        entry_valid_memory [0:VL_TABLE_DEPTH-1];

    reg [VL_INDEX_WIDTH-1:0] initialization_address;
    reg [VL_INDEX_WIDTH-1:0] sequence_check_address;
    reg [15:0] checked_vl_id;
    reg [7:0]  checked_sequence_number;
    reg        stored_entry_valid;
    reg [15:0] stored_vl_id;
    reg [7:0]  stored_sequence_number;
    reg [1:0]  sequence_check_state;

    wire [7:0] expected_sequence_number;
    wire       stored_entry_matches;
    wire       memory_write_enable;

    assign sequence_check_busy = !sequence_check_ready ||
                                 (sequence_check_state != CHECK_IDLE);
    assign expected_sequence_number = (stored_sequence_number == 8'd255) ?
                                      8'd1 : stored_sequence_number + 1'b1;
    assign stored_entry_matches = stored_entry_valid &&
                                  (stored_vl_id == checked_vl_id);
    assign memory_write_enable =
        (sequence_check_state == CHECK_COMPARE) &&
        (checked_sequence_number != 8'd0) &&
        !(stored_entry_matches &&
          (checked_sequence_number == stored_sequence_number));



    always @(posedge sys_clk) begin
        if (sequence_check_ready == 1'b0) begin
            entry_valid_memory[initialization_address] <= 1'b0;
        end
        else begin
            if (sequence_check_state == CHECK_READ) begin
                stored_entry_valid <=
                    entry_valid_memory[sequence_check_address];
                stored_vl_id <= vl_tag_memory[sequence_check_address];
                stored_sequence_number <=
                    sequence_number_memory[sequence_check_address];
            end

            if (memory_write_enable == 1'b1) begin
                entry_valid_memory[sequence_check_address] <= 1'b1;
                vl_tag_memory[sequence_check_address] <= checked_vl_id;
                sequence_number_memory[sequence_check_address] <=
                    checked_sequence_number;
            end
        end
    end

    always @(posedge sys_clk or negedge sys_rst_n) begin
        if (sys_rst_n == 1'b0) begin
            initialization_address <= {VL_INDEX_WIDTH{1'b0}};
            sequence_check_address <= {VL_INDEX_WIDTH{1'b0}};
            checked_vl_id          <= 16'd0;
            checked_sequence_number <= 8'd0;
            sequence_check_state   <= CHECK_IDLE;
            sequence_check_ready   <= 1'b0;
            sequence_check_done    <= 1'b0;
            sequence_check_passed  <= 1'b0;
            sequence_error         <= 1'b0;
            duplicate_frame        <= 1'b0;
        end
        else begin
            sequence_check_done   <= 1'b0;
            sequence_check_passed <= 1'b0;
            sequence_error        <= 1'b0;
            duplicate_frame       <= 1'b0;

            if (sequence_check_ready == 1'b0) begin
                if (initialization_address == VL_TABLE_DEPTH - 1) begin
                    initialization_address <= {VL_INDEX_WIDTH{1'b0}};
                    sequence_check_ready <= 1'b1;
                end
                else begin
                    initialization_address <= initialization_address + 1'b1;
                end
            end
            else begin
                case (sequence_check_state)
                    CHECK_IDLE: begin
                        if (sequence_check_start == 1'b1) begin
                            sequence_check_address <=
                                sequence_check_vl_id[VL_INDEX_WIDTH-1:0];
                            checked_vl_id <= sequence_check_vl_id;
                            checked_sequence_number <= sequence_check_number;
                            sequence_check_state <= CHECK_READ;
                        end
                    end

                    CHECK_READ: begin
                        sequence_check_state <= CHECK_COMPARE;
                    end

                    CHECK_COMPARE: begin
                        sequence_check_done <= 1'b1;


                        if (checked_sequence_number == 8'd0) begin
                            sequence_check_passed <= 1'b0;
                            sequence_error <= 1'b1;
                        end

                        else if ((stored_entry_valid == 1'b0) ||
                                 (stored_vl_id != checked_vl_id)) begin
                            sequence_check_passed <= 1'b1;
                        end

                        else if (checked_sequence_number ==
                                 stored_sequence_number) begin
                            sequence_check_passed <= 1'b0;
                            duplicate_frame <= 1'b1;
                        end

                        else if (checked_sequence_number ==
                                 expected_sequence_number) begin
                            sequence_check_passed <= 1'b1;
                        end

                        else begin
                            sequence_check_passed <= 1'b1;
                            sequence_error <= 1'b1;
                        end

                        sequence_check_state <= CHECK_IDLE;
                    end

                    default: sequence_check_state <= CHECK_IDLE;
                endcase
            end
        end
    end

;
    (* ram_style = "block" *) reg [DATA_WIDTH-1:0] memory [0:DEPTH-1];
    reg [ADDRESS_WIDTH-1:0] write_pointer, read_pointer;
    wire write_transfer = !srst && wr_en && !full;
    wire read_transfer = !srst && rd_en && !empty;
    assign full = (data_count == DEPTH);
    assign empty = (data_count == 0);

    always @(posedge clk) begin
        if (write_transfer) memory[write_pointer] <= din;
    end
    always @(posedge clk) begin
        if (srst) dout <= 0;
        else if (read_transfer) dout <= memory[read_pointer];
    end
    always @(posedge clk) begin
        if (srst) begin
            write_pointer <= 0; read_pointer <= 0; data_count <= 0;
        end else begin
            if (write_transfer) write_pointer <= write_pointer + 1'b1;
            if (read_transfer) read_pointer <= read_pointer + 1'b1;
            case ({write_transfer,read_transfer})
                2'b10: data_count <= data_count + 1'b1;
                2'b01: data_count <= data_count - 1'b1;
                default: data_count <= data_count;
            endcase
        end
    end

;
    wire sys_rst_n = !reset;
    wire shared_app_ready;
    wire [7:0] core_data;
    wire core_valid, core_last, core_ready;
    wire [7:0] a_payload, b_payload;
    wire a_valid, a_last, a_ready, b_valid, b_last, b_ready;
    wire [15:0] a_vl_id, b_vl_id;
    wire [7:0] a_sn, b_sn;
    wire [11:0] a_rx_events, b_rx_events;
    wire tx_oversize, merge_duplicate_a, merge_duplicate_b;
    wire [35:0] stats_events;
    assign stats_events = {app_tx_valid && !app_tx_ready && sys_rst_n,
        app_rx_valid && app_rx_ready && app_rx_last,merge_duplicate_b,merge_duplicate_a,
        b_rx_events,a_rx_events,2'b00,tx_oversize,2'b00,
        tx_b_valid && tx_b_ready && tx_b_last,tx_a_valid && tx_a_ready && tx_a_last,
        app_tx_valid && app_tx_ready && app_tx_last};
    afdx_es_stats #(.APP_IDLE_TIMEOUT_CYCLES(TX_IDLE_TIMEOUT_CYCLES)) u_stats (
        .sys_clk(clk),.sys_rst_n(sys_rst_n),.events(stats_events),
        .app_tx_valid(app_tx_valid),.app_tx_ready(app_tx_ready),.app_tx_last(app_tx_last),
        .clear(stats_clear),.read_addr(stats_addr),.read_data(stats_rdata),.read_error(stats_error));


    assign app_tx_ready = shared_app_ready;

    afdx_es_tx #(.BAG_CYCLES(BAG_CYCLES),.DEST_MAC(DEST_MAC),.SRC_MAC(SRC_MAC),
        .SRC_IP(SRC_IP),.DEST_IP(DEST_IP),.SRC_PORT(SRC_PORT),.DEST_PORT(DEST_PORT)) u_tx (
        .sys_clk(clk),.sys_rst_n(sys_rst_n),.app_tx_data(app_tx_data),
